require "timekeeping_relay"

RSpec.describe TimekeepingRelay::HttpEndpoint do
  # "No token is written to a payload or a log line."
  # A transport failure must not raise an error whose message repeats the
  # request, because the job's error data and logs would then hold the token.
  it "answers a refused connection with a failed response that holds neither the token nor the URL" do
    token = "service-relay-secret-token"
    url = "http://127.0.0.1:1/relay-target-path"
    endpoint = described_class.new(url: url, token: token)
    batch = { "schema_version" => 1, "snapshots" => [] }

    response = endpoint.deliver(batch, idempotency_key: "8f14e45f-ceea-567a-8f9e-2b6c1a2f6d3e")

    expect(response.status).not_to eq(200)
    expect(response.inspect).not_to include(token)
    expect(response.inspect).not_to include("relay-target-path")
  end
end

require "socket"

RSpec.describe TimekeepingRelay::HttpEndpoint, "on the wire" do
  # One-request HTTP server on a free local port. It records the raw request
  # and answers with the given status line and body, or never answers.
  def serve_once(answer: nil)
    server = TCPServer.new("127.0.0.1", 0)
    captured = Queue.new
    thread = Thread.new do
      client = server.accept
      head = +""
      head << client.gets until head.end_with?("\r\n\r\n")
      length = head[/^content-length:\s*(\d+)/i, 1].to_i
      captured << { head:, body: client.read(length) }
      if answer
        client.write("HTTP/1.1 #{answer.fetch(:status)}\r\nContent-Type: application/json\r\n" \
                     "Content-Length: #{answer.fetch(:body).bytesize}\r\nConnection: close\r\n\r\n#{answer.fetch(:body)}")
        client.close
      else
        sleep 2
      end
    end
    yield "http://127.0.0.1:#{server.addr[1]}", captured
  ensure
    thread&.kill
    server&.close
  end

  it "posts the batch as JSON with the bearer token and Idempotency-Key to the snapshot path" do
    batch = { "schema_version" => 1, "snapshots" => [{ "generation" => 1, "outbox_position" => 2, "entry" => { "id" => 9 } }] }
    serve_once(answer: { status: "200 OK", body: '{"applied":1,"ignored":0}' }) do |url, captured|
      endpoint = described_class.new(url:, token: "relay-wire-token")

      response = endpoint.deliver(batch, idempotency_key: "8f14e45f-ceea-567a-8f9e-2b6c1a2f6d3e")
      request = captured.pop

      expect(response).to eq(TimekeepingRelay::Response.new(status: 200, body: { "applied" => 1, "ignored" => 0 }))
      expect(request[:head]).to start_with("POST /internal/v1/timekeeping/entry-snapshots HTTP/1.1\r\n")
      expect(request[:head]).to match(/^Authorization: Bearer relay-wire-token\r$/i)
      expect(request[:head]).to match(/^Idempotency-Key: 8f14e45f-ceea-567a-8f9e-2b6c1a2f6d3e\r$/i)
      expect(request[:head]).to match(%r{^Content-Type: application/json\r$}i)
      expect(JSON.parse(request[:body])).to eq(batch)
    end
  end

  it "answers a read timeout with a failed response that holds neither the token nor the URL" do
    serve_once do |url, _captured|
      endpoint = described_class.new(url: "#{url}/", token: "relay-timeout-token", read_timeout: 0.2)

      response = endpoint.deliver({ "schema_version" => 1, "snapshots" => [] }, idempotency_key: "key")

      expect(response.status).to be_nil
      expect(response.body).to be_nil
      expect(response.inspect).not_to include("relay-timeout-token")
      expect(endpoint.inspect).not_to include("relay-timeout-token")
    end
  end

  it "keeps a non-JSON answer's text out of the response" do
    serve_once(answer: { status: "502 Bad Gateway", body: "proxy echoed Bearer relay-echo-token" }) do |url, _captured|
      response = described_class.new(url:, token: "relay-echo-token").deliver({ "snapshots" => [] }, idempotency_key: "key")

      expect(response).to eq(TimekeepingRelay::Response.new(status: 502, body: nil))
    end
  end

  it "posts nothing when the URL or token is missing" do
    batch = { "schema_version" => 1, "snapshots" => [] }

    expect(described_class.new(url: nil, token: "t").deliver(batch, idempotency_key: "key").status).to be_nil
    expect(described_class.new(url: "not a url", token: "t").deliver(batch, idempotency_key: "key").status).to be_nil
    expect(described_class.new(url: "http://127.0.0.1:1", token: "").deliver(batch, idempotency_key: "key").status).to be_nil
  end
end
